module tb_TopModule;
    reg a, b, c, d;
    wire q;

    TopModule uut (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .q(q)
    );

    initial begin
        integer i;
        for (i = 0; i < 16; i = i + 1) {
            {a, b, c, d} = i[3:0];
            #5;
            if (q !== (b | c)) begin
                $display("SELFFAIL: a=%b b=%b c=%b d=%b -> q=%b (expected %b)", a, b, c, d, q, b | c);
                $finish;
            end
        }
        $display("SELFTEST PASS");
        $finish;
    end
endmodule

